// Photo asset "easel" — added by the builder (their own real, local image).
// Use it in any page with:
//   <script src="./assets/easel.js"></script>
//   <img data-asset="easel" alt="describe the photo">
window.ASSETS = Object.assign(window.ASSETS || {}, { "easel": "data:image/jpeg;base64," });
(function () {
  function apply() { document.querySelectorAll('img[data-asset="easel"]').forEach(function (img) { img.src = window.ASSETS["easel"]; }); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply); else apply();
})();
